import { readFile } from "node:fs/promises";
import { createForks } from "@tigrisdata/agent-kit";
import { put } from "@tigrisdata/storage";

async function main() {
  try {
    // 1. Read the current trial id
    const trialId = (await readFile("/logs/artifacts/trial_id", "utf-8")).trim();

    // 2. Compute bucket names
    const sourceBucket = `harbor-source-${trialId}`;
    const forkPrefix = `harbor-fork-${trialId}`;

    // 3. Call createForks
    const response = await createForks(sourceBucket, 3, { prefix: forkPrefix });

    // 4. Check for error
    if (response.error) {
      console.error("Error creating forks:", response.error);
      process.exit(1);
    }

    const forkSet = response.data;
    if (!forkSet || !forkSet.forks || forkSet.forks.length !== 3) {
      console.error("Invalid response data from createForks");
      process.exit(1);
    }

    // 5. Fan out in parallel to write worker/output.txt into each fork
    await Promise.all(
      forkSet.forks.map((fork, i) => {
        return put("worker/output.txt", `worker-${i}`, {
          config: { bucket: fork.bucket },
        });
      })
    );

    // 6. Print the resulting fork bucket names to stdout
    forkSet.forks.forEach((fork) => {
      console.log(fork.bucket);
    });
  } catch (error) {
    console.error("Unexpected error:", error);
    process.exit(1);
  }
}

main();

